package net.officefloor.hq.app.person;

/** A person on a sheet: a name and a grade (A, B or C). */
public record Person(long id, String sheetId, String name, String grade) {
}
package net.officefloor.hq.app.person;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** People by sheet, in the order they were added. */
@Repository
public class PersonRepository {

    private static final RowMapper<Person> ROW = (rs, i) -> new Person(rs.getLong("id"),
            rs.getString("sheet_id"), rs.getString("name"), rs.getString("grade"));

    private final JdbcTemplate jdbc;

    public PersonRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Person> list(String sheetId) {
        return jdbc.query("SELECT * FROM person WHERE sheet_id = ? ORDER BY id", ROW, sheetId);
    }

    /** The person on this sheet, or null when absent. */
    public Person find(String sheetId, long id) {
        return jdbc.query("SELECT * FROM person WHERE sheet_id = ? AND id = ?", ROW, sheetId, id)
                .stream().findFirst().orElse(null);
    }

    /** Whether another person on this sheet (other than exceptId, when given) has this name,
     *  compared without regard to case and ignoring surrounding spaces. */
    public boolean nameInUse(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?)) AND id <> ?",
                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
        return n != null && n > 0;
    }

    public Person insert(String sheetId, String name, String grade) {
        var keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO person (sheet_id, name, grade) VALUES (?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setString(3, grade);
            return ps;
        }, keys);
        return new Person(keys.getKey().longValue(), sheetId, name, grade);
    }

    public void update(Person person) {
        jdbc.update("UPDATE person SET name = ?, grade = ? WHERE sheet_id = ? AND id = ?",
                person.name(), person.grade(), person.sheetId(), person.id());
    }
}
package net.officefloor.hq.app.person;

/** Body of a person add or edit: who is making it, and the person's name and grade. */
public record PersonRequest(String user, String name, String grade) {
}
package net.officefloor.hq.app.person;

public record PersonResponse(long id, String name, String grade) {
    public static PersonResponse from(Person p) {
        return new PersonResponse(p.id(), p.name(), p.grade());
    }
}
package net.officefloor.hq.app.person;

import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a name is required, the grade
 *  is one of A, B or C. Publishes the request with its name trimmed. */
public class ValidatePerson {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before changing people.");
        }
        String name = request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required.");
        }
        if (name.length() > 200) {
            throw new InvalidPersonException("A name is at most 200 characters.");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        body.set(new PersonRequest(request.user().trim(), name, grade));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Fails when the person is not on the sheet. */
public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonRepository repository, Out<Person> person) throws PersonNotFoundException {
        Person found = null;
        try {
            found = repository.find(sheetId.trim(), Long.parseLong(personId.trim()));
        } catch (NumberFormatException e) {
            // not an id: not found
        }
        if (found == null) {
            throw new PersonNotFoundException(personId);
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Apply the edit to the loaded person and store it. */
public class SavePerson {
    public void save(@Val PersonRequest request, @Val Person loaded, PersonRepository repository,
            Out<PersonResponse> saved) {
        Person person = new Person(loaded.id(), loaded.sheetId(), request.name(), request.grade());
        repository.update(person);
        saved.set(PersonResponse.from(person));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record the stored edit in the audit file. */
public class AuditPersonEdited {
    public void audit(@Val PersonRequest request, @Val Person loaded, @Val PersonResponse saved, Audit audit) {
        audit.record("PERSON_EDITED sheet=" + loaded.sheetId() + " by=" + request.user()
                + " name=" + saved.name() + " grade=" + saved.grade());
    }
}
package net.officefloor.hq.app.person;

/** A person add or edit to a name another person on the sheet already has. */
public class DuplicatePersonNameException extends Exception {
    public DuplicatePersonNameException(String name) {
        super("The name " + name + " is already in use on this sheet.");
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleDuplicatePersonName {
    public void handle(@Parameter DuplicatePersonNameException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Refuse renaming a person to a name another person on the sheet already has. */
public class ValidatePersonName {
    public void validate(@Val PersonRequest request, @Val Person loaded, PersonRepository repository)
            throws DuplicatePersonNameException {
        if (repository.nameInUse(loaded.sheetId(), request.name(), loaded.id())) {
            throw new DuplicatePersonNameException(request.name());
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val PersonResponse person, ObjectResponse<PersonResponse> response) {
        response.send(person);
    }
}
-- People on a sheet, listed in the order they were added (by id). Grade is one of A, B or C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet(id),
    name     VARCHAR(200) NOT NULL,
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person(sheet_id, id);
-- Who opened a claim (the signed-in user's name). NULL while a draft. They may not settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(100);
